function explicarErro(onde, porque) {
  const texto = `${onde} ${porque}`;
  return EXPLICA_ERRO.find((e) => e.quando.test(texto)) || null;
}

/* Nem todo erro e' do dono.

   "nao consegui dar o cargo" e' configuracao do servidor do CLIENTE: o cargo
   do bot esta abaixo do cargo da pessoa, e quem arruma e' um administrador de
   la', arrastando. O painel daquele cliente ja diz isso em vermelho, com o
   passo a passo.

   Mandar pro canal de erros do dono, a cada reinicio, e' barulho sobre algo
   que ele nao pode consertar -- e barulho no canal de erro tem um preco
   especifico: ensina a ignorar o canal. Estes continuam na lista do /admin,
   que e' onde se procura quando se quer procurar. */
const ERRO_DO_CLIENTE = [
  /nao consegui dar o cargo/i,
  /nao consegui tirar o cargo/i,
  /Missing Permissions/i,
  /Missing Access/i,
];

/* A hora no relogio de QUEM LE, nao no meu.

   A maquina roda em UTC, e eu formatava com toLocaleTimeString("pt-BR"): o
   cartao dizia 06:06 enquanto o Discord, dois centimetros ao lado, dizia
   03:06. Duas horas para o mesmo instante na mesma tela -- e a errada era a
   minha, com cara de certa porque estava em portugues.

   O <t:...> e' o formato do proprio Discord: mando o instante, cada pessoa ve
   no fuso dela. Ele nao vale em rodape nem em titulo, so' no corpo -- e onde
   a hora precisava ficar no rodape, quem resolve e' o campo `timestamp` do
   embed, que o Discord tambem desenha no fuso de quem le. */
function quandoFoi(ms = Date.now(), estilo = "T") {
  return `<t:${Math.floor(ms / 1000)}:${estilo}>`;
}

/* ---------------- os erros que se organizam sozinhos ----------------

   O canal de erros era uma fila de mensagens: cada aviso uma nova, e o mesmo
   problema aparecia dez vezes espalhado no meio de outros. Para saber o que
   estava aberto era preciso ler tudo.

   Agora cada TIPO de erro tem UM cartao, editado no lugar: quantas vezes,
   desde quando, a ultima, e em que pe' esta' -- aberto, consertando,
   resolvido ou silenciado. Quando e' hora de chamar atencao (primeira vez,
   ou o recuo do aviso liberou), o cartao desce para o fim do canal; no resto
   do tempo ele so' muda o numero, calado. Um quadro fixado no topo lista o
   que esta' aberto.

   A ficha mora tambem no banco (cyron_erro), e e' ela a fila de conserto:
   quem consertar muda o status la', e o cartao acompanha na proxima hora.
   Erro que passa 24 horas sem aparecer fecha sozinho; se voltar, reabre e
   desce de novo. */
const fichasDeErro = new Map();   // id -> { chave, onde, porque, explicado, precisa, novas, base, destacar }
const statusDesenhado = new Map();   // id -> status que o cartao mostra
const ERRO_FECHA_SOZINHO = 24 * 60 * 60 * 1000;
let descargaDeErros = null;

function idDoErro(chave) {
  return createHash("sha1").update(String(chave)).digest("hex").slice(0, 16);
}

function contarErro(chave, { onde, porque, explicacao, agora = Date.now() }) {
  const id = idDoErro(chave);
  const f = fichasDeErro.get(id) || { id, chave, novas: 0, base: null, destacar: false };
  f.titulo = explicacao?.titulo || `${onde}: ${String(porque).slice(0, 80)}`;
  f.onde = String(onde).slice(0, 120);
  f.porque = String(porque || "").slice(0, 500);
  f.explicado = !!explicacao;
  f.precisa = !!explicacao?.precisaDeVoce;
  f.novas += 1;
  f.ultimo = agora;
  fichasDeErro.set(id, f);
  agendarDescargaDeErros();
}

/* O cartao que o anotarErro montou, e o pedido de descer para o fim. */
function mostrarErro(chave, corpo) {
  const f = fichasDeErro.get(idDoErro(chave));
  if (!f) return;
  f.base = corpo?.embeds?.[0] || f.base;
  f.destacar = true;
  agendarDescargaDeErros();
}

/* Junta as ocorrencias de meio minuto numa ida so' ao banco e ao Discord:
   a queda do Supabase que gera trinta linhas vira uma edicao. */
function agendarDescargaDeErros(espera = 30 * 1000) {
  if (descargaDeErros) return;
  descargaDeErros = setTimeout(() => {
    descargaDeErros = null;
    descarregarErros().catch((e) => console.log("erros: descarga falhou:", e?.message || e));
  }, espera);
}

const STATUS_DO_ERRO = {
  aberto:      { emoji: "🔴", nome: "Aberto", cor: null },
  consertando: { emoji: "🔧", nome: "Consertando", cor: 0xC9A227 },
  resolvido:   { emoji: "✅", nome: "Resolvido", cor: 0x2E8B7A },
  silenciado:  { emoji: "🔇", nome: "Silenciado", cor: 0x6B7280 },
};
const CAMPOS_DA_FICHA = ["📊 Ocorrências", "📋 Status"];

/* O cartao de um erro: o que o anotarErro explicou, mais a ficha. Os dois
   campos da ficha sao trocados, nunca empilhados, entao da' para redesenhar a
   partir do cartao que ja' esta' no canal depois de um reinicio. */
function cartaoDoErro(base, linha, agora = Date.now()) {
  const st = STATUS_DO_ERRO[linha.status] || STATUS_DO_ERRO.aberto;
  const campos = (base?.fields || []).filter((c) => !CAMPOS_DA_FICHA.includes(c.name));
  const t = (iso) => Math.floor(Date.parse(iso) / 1000);
  const estado = linha.status === "silenciado" && linha.silencio_ate
    ? `${st.emoji} **${st.nome}** até <t:${t(linha.silencio_ate)}:f>`
    : `${st.emoji} **${st.nome}**`;
  return {
    ...(base || { title: `❔ ${String(linha.titulo || linha.onde).slice(0, 200)}`,
      fields: [{ name: "O que aconteceu", value: `\`\`\`\n${String(linha.onde)}: ${String(linha.porque).slice(0, 900)}\n\`\`\`` }] }),
    ...(st.cor ? { color: st.cor } : {}),
    fields: [
      ...campos.slice(0, 20),
      { name: CAMPOS_DA_FICHA[0], inline: true,
        value: `**${linha.vezes}x** · desde <t:${t(linha.primeiro_em)}:d>\núltima <t:${t(linha.ultimo_em)}:R>` },
      { name: CAMPOS_DA_FICHA[1], inline: true,
        value: (estado + (linha.nota ? `\n${String(linha.nota).slice(0, 300)}` : "")).slice(0, 1024) },
    ],
    footer: { text: `${String(linha.onde).slice(0, 100)} · ficha ${linha.chave}` },
    timestamp: new Date(agora).toISOString(),
  };
}

function botoesDoErro(linha) {
  const b = (acao, emoji, label, style = 2) =>
    ({ type: 2, custom_id: `erro:${acao}:${linha.chave}`, style, emoji: { name: emoji }, label });
  if (linha.status === "resolvido" || linha.status === "silenciado") {
    return [{ type: 1, components: [b("reabrir", "↩️", "Reabrir")] }];
  }
  return [{ type: 1, components: [
    b("resolvido", "✅", "Resolvido", 3),
    b("consertando", "🔧", "Estou consertando"),
    b("silenciar", "🔇", "Silenciar 7 dias"),
  ] }];
}

async function canalDeErros() {
  const gid = await guildDoPainel();
  const guild = gid && client.guilds.cache.get(gid);
  return guild?.channels.cache.find((c) => c.type === ChannelType.GuildText && c.name === CANAL_ERROS) || null;
}

async function linhaDoErro(id) {
  return (await sb(`cyron_erro?chave=eq.${id}&select=*`).catch(() => null))?.[0] || null;
}

/* O que muda na ficha com as ocorrencias novas. Sem rede: entra a linha do
   banco (ou nada), sai a linha nova e se o cartao desce. */
function proximaFicha(antes, f, agora = Date.now()) {
  const linha = { ...(antes || {
    chave: f.id, status: "aberto", vezes: 0, primeiro_em: new Date(f.ultimo || agora).toISOString(),
  }) };
  linha.titulo = f.titulo; linha.onde = f.onde; linha.porque = f.porque;
  linha.explicado = f.explicado; linha.precisa_de_voce = f.precisa;
  linha.vezes = Number(linha.vezes || 0) + f.novas;
  linha.ultimo_em = new Date(f.ultimo || agora).toISOString();
  let destacar = f.destacar || !antes || !antes.msg_id;
  if (linha.status === "resolvido") {
    linha.status = "aberto";
    linha.nota = "voltou a acontecer depois de resolvido";
    destacar = true;
  }
  if (linha.status === "silenciado") {
    if (linha.silencio_ate && Date.parse(linha.silencio_ate) > agora) destacar = false;
    else { linha.status = "aberto"; linha.silencio_ate = null; linha.nota = "o silêncio acabou e ele continua"; }
  }
  return { linha, destacar };
}

async function descarregarErros(agora = Date.now()) {
  const canal = await canalDeErros();
  for (const f of [...fichasDeErro.values()]) {
    if (!f.novas && !f.destacar) continue;
    /* A memoria segura o cartao quando o banco nao responde (ou a tabela
       ainda nao existe): sem ela, cada descarga postaria um cartao novo. */
    const { linha, destacar } = proximaFicha((await linhaDoErro(f.id)) || f.linha || null, f, agora);
    f.novas = 0; f.destacar = false;
    if (canal) {
      const cartao = { embeds: [cartaoDoErro(f.base, linha, agora)], components: botoesDoErro(linha) };
      const velha = linha.msg_id ? await canal.messages.fetch(linha.msg_id).catch(() => null) : null;
      if (velha && !destacar) {
        await velha.edit(cartao).catch(() => {});
      } else {
        const nova = await canal.send({ ...cartao, allowedMentions: { parse: [] } }).catch(() => null);
        if (nova) {
          await velha?.delete().catch(() => {});
          linha.msg_id = nova.id;
        }
      }
    }
    f.linha = linha;
    statusDesenhado.set(linha.chave, `${linha.status}|${linha.nota || ""}`);
    await sbPost("cyron_erro", linha, "resolution=merge-duplicates")
      .catch((e) => console.log("erros: nao consegui guardar a ficha:", e?.message || e));
  }
  await desenharQuadroDeErros(canal, agora).catch(() => {});
}

/* O quadro fixado: o que esta' aberto, do mais repetido ao menos, com o
   atalho para cada cartao. */
async function desenharQuadroDeErros(canal, agora = Date.now()) {
  if (!canal) return;
  const linhas = await sb("cyron_erro?status=in.(aberto,consertando)&select=*&order=vezes.desc&limit=20")
    .catch(() => null);
  if (!linhas) return;
  const link = (l) => (l.msg_id ? ` · [ver](https:` + `//discord.com/channels/${canal.guild.id}/${canal.id}/${l.msg_id})` : "");
  const embed = {
    color: linhas.some((l) => l.precisa_de_voce) ? 0xE03E3E : linhas.length ? 0xC9A227 : 0x2E8B7A,
    title: `📋 Quadro de erros — ${linhas.length} em aberto`,
    description: linhas.length
      ? linhas.map((l) => `${(STATUS_DO_ERRO[l.status] || STATUS_DO_ERRO.aberto).emoji} **${String(l.titulo).slice(0, 70)}** ` +
          `×${l.vezes} · <t:${Math.floor(Date.parse(l.ultimo_em) / 1000)}:R>${link(l)}`).join("\n").slice(0, 4000)
      : "✅ Nada em aberto.",
    footer: { text: "cada erro tem um cartão só, editado no lugar · fecha sozinho depois de 24h sem aparecer" },
    timestamp: new Date(agora).toISOString(),
  };
  const guardado = (await ajustes()).erros_quadro_msg;
  const velho = guardado ? await canal.messages.fetch(guardado).catch(() => null) : null;
  if (velho) return void await velho.edit({ embeds: [embed] }).catch(() => {});
  const novo = await canal.send({ embeds: [embed], allowedMentions: { parse: [] } }).catch(() => null);
  if (!novo) return;
  await novo.pin("quadro de erros").catch(() => {});
  await apagarAvisoDeFixado(canal, novo.id);
  await porAjuste("erros_quadro_msg", novo.id);
}

/* De hora em hora: fecha o que parou de acontecer e redesenha o cartao de
   quem mudou de status por fora (quem consertou mexeu no banco). */
function revisaoDoErro(linha, agora = Date.now()) {
  if (linha.status === "aberto" && agora - Date.parse(linha.ultimo_em) > ERRO_FECHA_SOZINHO) {
    return { ...linha, status: "resolvido", nota: "parou de acontecer sozinho (24h sem aparecer)" };
  }
  if (linha.status === "silenciado" && linha.silencio_ate && Date.parse(linha.silencio_ate) <= agora) {
    return { ...linha, status: "resolvido", silencio_ate: null, nota: "o silêncio acabou sem ele voltar" };
  }
  return linha;
}

async function revisarErros(agora = Date.now()) {
  const canal = await canalDeErros();
  const linhas = await sb("cyron_erro?status=neq.resolvido&select=*").catch(() => null) || [];
  const recentes = await sb(`cyron_erro?status=eq.resolvido&ultimo_em=gte.${new Date(agora - 7 * 864e5).toISOString()}&select=*`)
    .catch(() => null) || [];
  for (const antes of [...linhas, ...recentes]) {
    const linha = revisaoDoErro(antes, agora);
    if (linha !== antes) await sbPatch(`cyron_erro?chave=eq.${linha.chave}`, { status: linha.status, nota: linha.nota, silencio_ate: linha.silencio_ate ?? null }).catch(() => {});
    if (statusDesenhado.get(linha.chave) === `${linha.status}|${linha.nota || ""}`) continue;
    statusDesenhado.set(linha.chave, `${linha.status}|${linha.nota || ""}`);
    const msg = canal && linha.msg_id ? await canal.messages.fetch(linha.msg_id).catch(() => null) : null;
    if (!msg) continue;
    const base = fichasDeErro.get(linha.chave)?.base || msg.embeds?.[0]?.toJSON?.() || null;
    await msg.edit({ embeds: [cartaoDoErro(base, linha, agora)], components: botoesDoErro(linha) }).catch(() => {});
  }
  await desenharQuadroDeErros(canal, agora).catch(() => {});
}

/* Os botoes do cartao. So' o dono do bot. */
async function cliqueDoErro(inter) {
  if (!await ehDono(inter.user.id)) return inter.reply({ flags: 64, content: "Não conheço esse comando." });
  const [, acao, chave] = inter.customId.split(":");
  const agora = Date.now();
  const mudanca = {
    resolvido: { status: "resolvido", nota: `marcado como resolvido por ${inter.user.username}` },
    consertando: { status: "consertando", nota: `${inter.user.username} está consertando` },
    silenciar: { status: "silenciado", silencio_ate: new Date(agora + 7 * 864e5).toISOString(), nota: null },
    reabrir: { status: "aberto", silencio_ate: null, nota: `reaberto por ${inter.user.username}` },
  }[acao];
  if (!mudanca || !/^[0-9a-f]{16}$/.test(chave || "")) return inter.reply({ flags: 64, content: "Botão velho." });
  await inter.deferUpdate();
  await sbPatch(`cyron_erro?chave=eq.${chave}`, mudanca).catch(() => {});
  const linha = await linhaDoErro(chave);
  if (!linha) return;
  statusDesenhado.set(chave, `${linha.status}|${linha.nota || ""}`);
  const base = fichasDeErro.get(chave)?.base || inter.message?.embeds?.[0]?.toJSON?.() || null;
  await inter.editReply({ embeds: [cartaoDoErro(base, linha, agora)], components: botoesDoErro(linha) }).catch(() => {});
  await desenharQuadroDeErros(await canalDeErros(), agora).catch(() => {});
}

function anotarErro(onde, porque) {
  errosRecentes.push({ quando: Date.now(), onde, porque: String(porque || "").slice(0, 300) });
  if (errosRecentes.length > MAX_ERROS) errosRecentes.shift();

  const texto = `${onde} ${porque}`;
  if (ERRO_DO_CLIENTE.some((r) => r.test(texto))) return;

  const explicacao = explicarErro(onde, porque);

  /* A repeticao junta pela EXPLICACAO, nao pelo texto cru.

     O Supabase caiu por trinta segundos e saiu uma linha por servidor: seis
     mensagens seguidas dizendo a mesma coisa com um numero diferente no meio.
     Pra quem le, seis problemas. Era um. Agrupando pelo que aquilo QUER
     DIZER, o mesmo tombo vira uma mensagem, e a janela de silencio depois
     dela vale pro problema inteiro. */
  const chave = explicacao ? `explicado|${explicacao.titulo}` : `${onde}|${String(porque).slice(0, 60)}`;
  const agora = Date.now();
  const hist = registrarOcorrencia(historicoDoAviso, chave, agora);
  /* Toda ocorrencia conta na ficha do erro, mesmo quando nao e' hora de
     falar: o cartao se atualiza calado, e o numero nunca mente. */
  contarErro(chave, { onde, porque, explicacao, agora });
  const plano = planoDoAviso(hist, agora);
  if (!plano.falar) return;
  hist.avisos += 1;
  hist.avisoEm = agora;
  jaAvisado.set(chave, agora);

  /* A linha que faltava nos quarenta e oito cartoes: quantas vezes, e desde
     quando. Sem ela cada cartao parece o primeiro. */
  const teimosia = hist.vezes > 1
    ? `\n\nAconteceu **${hist.vezes} vezes** desde ${quandoFoi(hist.desde, "f")}.` +
      (plano.espera >= ESPERA_AVISO_MAX
        ? " Daqui pra frente eu aviso no máximo uma vez por dia."
        : "")
    : "";
  const desmentida = promessaDesmentida(explicacao, hist, agora);

  if (!explicacao) {
    /* Erro que eu ainda nao sei explicar. Aparece cru e ASSUMIDO como cru --
       fingir gravidade que eu nao sei medir seria pedir preocupacao no
       escuro. */
    mostrarErro(chave, {
      embeds: [{
        color: 0x9aa0a6,
        title: "❔ Um erro que eu ainda não sei explicar",
        description: `Me mostre esta mensagem e eu passo a explicar este aqui também.\n\n` +
          `\`\`\`\n${onde}: ${porque}\n\`\`\`` + teimosia,
        footer: { text: "sem tradução para o português ainda" },
        timestamp: new Date().toISOString(),
      }],
    }).catch(() => {});
    return;
  }

  /* O DESMENTIDO.

     Aqui o cartao para de repetir a promessa e admite que ela nao se
     sustentou. Nao e' enfeite: e' a unica parte deste arquivo que consegue
     descobrir que eu errei, porque nao depende de eu ter classificado o
     evento certo -- depende da realidade discordar de mim. */
  const urgente = explicacao.precisaDeVoce || desmentida;
  const campos = desmentida
    ? [
        {
          name: "Eu disse que isto se resolvia sozinho",
          value: `E já disse **${hist.vezes} vezes**, desde ${quandoFoi(hist.desde, "f")}. ` +
            "Não está se resolvendo.\n\nOu o conserto automático não está pegando, ou esta " +
            "explicação está errada. Nos dois casos, quem precisa olhar é você.",
        },
        { name: "O que eu vinha dizendo", value: explicacao.oque.slice(0, 900) },
      ]
    : [
        { name: "O que aconteceu", value: (explicacao.oque + teimosia).slice(0, 1000) },
        {
          name: explicacao.precisaDeVoce ? "O que fazer" : "Precisa de você?",
          value: (explicacao.precisaDeVoce ? "" : "**Não.** ") + explicacao.fazer.slice(0, 900),
        },
      ];

  mostrarErro(chave, {
    embeds: [{
      color: urgente ? 0xE03E3E : 0x9aa0a6,
      title: `${desmentida ? "🔁" : urgente ? "🔴" : "⚪"} ${explicacao.titulo}`,
      fields: campos,
      footer: { text: `${onde}: ${String(porque).slice(0, 120)}` },
      timestamp: new Date().toISOString(),
    }],
  }).catch(() => {});
}

const CANAL_NOVOS = "📥-novos";
const CANAL_PAGAMENTOS = "💳-pagamentos";
const CANAL_ERROS = "🐛-erros";
const CANAL_CLIENTES = "📋-clientes";
const CANAL_DIARIO = "📊-diário";
const CANAL_ANALITICO = "📈-analitico";

/* Quem pode abrir o painel do dono.

   Pergunto ao Discord de quem e' o aplicativo, em vez de guardar um id numa
   variavel. Id escrito na mao envelhece calado: no dia em que a conta mudar
   ou o app virar de um time, ninguem lembra de atualizar, e o painel some pro
   dono legitimo.

   Vou direto na API em vez de usar o objeto que o discord.js guarda. A
   primeira versao usava client.application.owner, e ele nem sempre vem
   preenchido -- quando nao vinha, meu catch devolvia "nao e' o dono" sem
   dizer nada, e o dono de verdade levava "Não conheço esse comando" na cara
   sem nenhuma pista do motivo. Foi o que aconteceu no primeiro teste.

   A lista "donos" nos ajustes existe pra quem tem mais de uma conta -- o caso
   comum de quem criou o aplicativo numa e usa o Discord noutra. */
let cacheDonos = { v: null, t: 0 };

async function idsDeDono() {
  if (cacheDonos.v && Date.now() - cacheDonos.t < 10 * 60 * 1000) return cacheDonos.v;
  const ids = new Set();
  try {
    const r = await fetch(`${API}/applications/@me`, { headers: { Authorization: `Bot ${TOKEN}` } });
    if (r.ok) {
      const app = await r.json();
      if (app?.owner?.id) ids.add(String(app.owner.id));
      for (const m of app?.team?.members || []) if (m?.user?.id) ids.add(String(m.user.id));
    } else {
      console.error(`admin: nao consegui saber de quem e o aplicativo: HTTP ${r.status}`);
    }
  } catch (e) {
    console.error("admin: nao consegui saber de quem e o aplicativo:", e?.message || e);
  }
  for (const extra of String((await ajustes()).donos || "").split(/[,\s]+/)) {
    if (/^\d{5,}$/.test(extra)) ids.add(extra);
  }
  if (ids.size) cacheDonos = { v: ids, t: Date.now() };
  return ids;
}

async function ehDono(userId) {
  const ids = await idsDeDono();
  const pode = ids.has(String(userId));
  /* Recusa deixa rastro. Sem isto, "não conheço esse comando" e' indistinguivel
     de "eu nao consegui descobrir quem e' o dono" -- que foi exatamente a
     duvida que me custou tempo. */
  if (!pode) console.log(`admin: recusei ${userId}; donos conhecidos: ${[...ids].join(",") || "NENHUM"}`);
  return pode;
}

async function guildDoPainel() {
  return (await ajustes()).admin_guild || "";
}

async function ehOPainel(guildId) {
  return !!guildId && guildId === await guildDoPainel();
}

/* Nome de canal a partir do nome do servidor.

   Discord so' aceita minusculas, sem espaco e sem acento. Um servidor chamado
   "Servidor de 𝐹𝑒𝓇𝓃𝒶𝓃𝒹𝑜 †" vira "servidor-de-fernando" -- e se sobrar vazio
   (nome so' de simbolos, que existe), cai no id, que nunca e' vazio. */
function nomeDeCanal(nome, id) {
  const limpo = String(nome || "")
    .normalize("NFD").replace(/[̀-ͯ]/g, "")
    .toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 90);
  return limpo || `servidor-${String(id).slice(-6)}`;
}

async function canalDoPainel(guild, nome, categoria) {
  const achado = guild.channels.cache.find(
    (c) => c.type === ChannelType.GuildText && c.name === nome);
  if (achado) return achado;
  return await guild.channels.create({
    name: nome, type: ChannelType.GuildText,
    ...(categoria ? { parent: categoria.id } : {}),
    reason: "painel de administração da CYRON",
  }).catch((e) => {
    console.error("painel: nao consegui criar", nome, e?.message || e);
    return null;
  });
}

/* O canal de pagamentos precisa de uma boca que a funcao do Stripe alcance.

   Quem recebe o aviso de pagamento e' a edge function, que roda no Supabase e
   nao fala com o gateway do Discord. Um webhook resolve: o bot cria, guarda a
   URL nos ajustes, e a funcao so' faz um POST. Sem isso o canal existiria
   mudo -- que foi como ele nasceu.

   Reaproveito o que ja existe: criar um webhook novo a cada volta do relogio
   encheria o canal de webhooks orfaos ate' bater no limite de 15. */
async function garantirWebhookDePagamentos(guild) {
  try {
    const a = await ajustes();
    if (a.webhook_pagamentos) return;

    const canal = guild.channels.cache.find(
      (c) => c.type === ChannelType.GuildText && c.name === CANAL_PAGAMENTOS);
    if (!canal) return;

    const existentes = await canal.fetchWebhooks().catch(() => null);
    const meu = existentes?.find((w) => w.owner?.id === client.user.id);
    const w = meu || await canal.createWebhook({ name: "CYRON pagamentos" });
    await porAjuste("webhook_pagamentos", w.url);
    console.log("painel: webhook de pagamentos pronto");
  } catch (e) {
    console.error("painel: nao consegui preparar o webhook de pagamentos:", e?.message || e);
  }
}

/* Acha o topico do cliente, ou abre um.

   Guardo o id, nunca procuro pelo nome: servidor muda de nome, e busca por
   nome vira topico duplicado no dia da primeira renomeacao.

   Uma semana de auto-arquivamento: quem esta em uso fica a vista, quem
   esfriou sai da frente sem sumir. */
async function topicoDoCliente(guild, canal, servidor) {
  if (servidor.canal_admin) {
    const achado = await guild.channels.fetch(servidor.canal_admin).catch(() => null);
    if (achado) {
      /* O servidor mudou de nome: o topico muda junto. Topico arquivado nao
         aceita edicao, entao desarquivar vai na mesma chamada -- e ele volta a
         arquivar sozinho na semana sem movimento. */
      const esperado = nomeDeCanal(servidor.nome, servidor.guild_id).slice(0, 90);
      if (achado.name !== esperado) {
        await achado.edit({ name: esperado, archived: false }, "o servidor mudou de nome")
          .catch((e) => console.error("painel: nao consegui renomear o tópico:", e?.message || e));
      }
      return achado;
    }
  }
  const topico = await canal.threads.create({
    name: nomeDeCanal(servidor.nome, servidor.guild_id).slice(0, 90),
    autoArchiveDuration: 10080,
    reason: "ficha do cliente no painel",
  }).catch((e) => {
    console.error("painel: nao consegui abrir o tópico:", e?.message || e);
    return null;
  });
  if (!topico) return null;
  await sbPatch(`cyron_servidor?id=eq.${encodeURIComponent(servidor.id)}`,
    { canal_admin: topico.id, msg_admin: null });
  servidor.canal_admin = topico.id;
  servidor.msg_admin = null;
  return topico;
}

/* Escreve num canal de acontecimento, se o painel existir.

   Nunca estoura: um aviso administrativo que derruba a operacao seria o
   cumulo. Se o painel nao existe ainda, a linha simplesmente nao e' escrita --
   o dado de verdade esta no banco de qualquer jeito. */
async function avisarNoPainel(nomeCanal, texto) {
  try {
    const gid = await guildDoPainel();
    if (!gid) return;
    const guild = client.guilds.cache.get(gid);
    if (!guild) return;
    const canal = guild.channels.cache.find(
      (c) => c.type === ChannelType.GuildText && c.name === nomeCanal);
    if (!canal) return;
    const corpo = typeof texto === "string"
      ? { content: texto.slice(0, 1900) }
      : texto;
    await canal.send({ ...corpo, allowedMentions: { parse: [] } });
  } catch (e) {
    console.error("painel: nao consegui avisar em", nomeCanal, e?.message || e);
  }
}

/* O cartao de um cliente: o que ele tem, o que ele usa, como esta.

   Mesmo padrao do painel do cliente -- mensagem fixada que se EDITA. Um canal
   por cliente com dez mensagens de estado velhas seria pior que nenhum canal:
   a pessoa leria a de cima achando que e' a atual. */
async function cartaoDoCliente(guild, servidor) {
  if (!servidor.canal_admin) return;
  const canal = await guild.channels.fetch(servidor.canal_admin).catch(() => null);
  if (!canal) return;

  const uso = await usoDeHoje(servidor.id);
  const sete = await sb(
    `cyron_uso_diario?servidor_id=eq.${servidor.id}&dia=gte.${new Date(Date.now() - 7 * 864e5).toISOString().slice(0, 10)}&select=caracteres,traducoes`) || [];
  const soma = sete.reduce((a, l) => ({
    c: a.c + Number(l.caracteres || 0), t: a.t + Number(l.traducoes || 0),
  }), { c: 0, t: 0 });

  const idiomas = await sb(`discord_chat_espelho?servidor_id=eq.${servidor.id}&select=idioma`) || [];
  const fontes = await sb(
    `discord_fonte_replica?servidor_id=eq.${servidor.id}&gera_replica=is.true&tipo=neq.${TIPO_AGENDA}&select=canal_id`) || [];
  const cliente = client.guilds.cache.get(String(servidor.guild_id));
  const plano = planoDe(servidor);
  const faixa = faixaDe(servidor);
  /* Quem e' o dono e como entrar: e' o que se precisa na hora de atender.
     O nome de usuario vem junto da mencao porque mencao de quem nao esta' no
     painel aparece como usuario desconhecido. */
  const dono = cliente?.ownerId ? await client.users.fetch(cliente.ownerId).catch(() => null) : null;
  const convite = cliente && !servidor.saiu_em ? await conviteDoServidor(cliente) : "";

  const embed = {
    color: servidor.saiu_em ? 0x8A3A33 : plano === "pago" ? 0x2E8B7A : 0xB08A2E,
    title: servidor.nome || nomeDeCanal(servidor.nome, servidor.guild_id),
    description: servidor.saiu_em
      ? `⚠️ **Me tiraram deste servidor** ${quandoFoi(Date.parse(servidor.saiu_em), "R")}.`
      : `${cliente ? `${cliente.memberCount} membros` : "_não estou vendo este servidor agora_"}`,
    fields: [
      { name: "Plano", value: plano === "pago" ? `🟢 ${nomeDaFaixa(faixa)}` : "⚪ grátis", inline: true },
      { name: "Idiomas", value: String(idiomas.length), inline: true },
      { name: "Canais traduzidos", value: String(fontes.length), inline: true },
      { name: "Hoje", value: `${uso.traducoes} traduções\n${(uso.caracteres / 1000).toFixed(1)}k caracteres`, inline: true },
      { name: "7 dias", value: `${soma.t} traduções\n${(soma.c / 1000).toFixed(1)}k caracteres`, inline: true },
      { name: "Motor", value: servidor.tradutor_motor && servidor.tradutor_motor !== "auto"
          ? `🔑 ${servidor.tradutor_motor}` : "⚪ google grátis", inline: true },
      { name: "👑 Dono", value: dono ? `<@${dono.id}> · ${dono.username}` : "—", inline: true },
      { name: "🔗 Servidor", value: convite || (cliente ? "_sem permissão para criar convite_" : "—"), inline: true },
      /* O problema do cliente aparece na ficha DELE, e nao no canal de erros
         do dono. Aqui ele e' contexto -- "por isso este servidor tem idioma e
         nao tem gente nas categorias" --, e nao um chamado. */
      ...(cargoAcimaDeMim.has(servidor.id) ? [{
        name: "⛔ Cargo fora de alcance",
        value: "Os cargos de idioma estão acima do meu neste servidor. " +
          "Ninguém recebe cargo até um administrador de lá arrastar a CYRON para cima.",
      }] : []),
    ],
    footer: { text: `guild ${servidor.guild_id} · instalado em ${new Date(servidor.criado_em).toLocaleDateString("pt-BR")}` },
  };

  const botoes = botoesDaFicha(servidor);
  const assinatura = assinaturaDoCartao(embed, botoes);
  if (jaDesenhado(servidor.msg_admin, assinatura)) return;
  if (servidor.msg_admin) {
    const antiga = await canal.messages.fetch(servidor.msg_admin).catch(() => null);
    if (antiga) {
      const antes = antiga.embeds?.[0]
        ? assinaturaDoCartao(antiga.embeds[0].toJSON(), (antiga.components || []).map((l) => l.toJSON()))
        : null;
      if (antes === assinatura) { marcarDesenhado(servidor.msg_admin, assinatura); return; }   // nada mudou

      /* Desarquiva SO' quando ha' o que escrever. Desarquivar a cada volta do
         relogio deixaria todos os topicos sempre ativos, e a barra lateral
         voltaria a ser a parede que o topico veio evitar. */
      if (canal.archived) await canal.setArchived(false, "ficha mudou").catch(() => {});
      await antiga.edit({ embeds: [embed], components: botoes });
      marcarDesenhado(servidor.msg_admin, assinatura);
      return;
    }
  }
  if (canal.archived) await canal.setArchived(false, "primeira ficha").catch(() => {});
  const nova = await canal.send({ embeds: [embed], components: botoesDaFicha(servidor) });
  await nova.pin("ficha do cliente").catch(() => {});
  await apagarAvisoDeFixado(canal, nova.id);
  await sbPatch(`cyron_servidor?id=eq.${encodeURIComponent(servidor.id)}`, { msg_admin: nova.id });
  servidor.msg_admin = nova.id;
}

/* Monta o painel inteiro: canais de acontecimento, categoria e um canal por
   cliente. Roda junto da volta do relogio, entao cliente novo ganha canal
   sozinho -- e cliente que ja tem canal so' tem a ficha atualizada. */
/* Uma montagem por vez.

   O painel duplicou todos os topicos na primeira vez que foi usado: o clique
   do dono disparou uma montagem e o relogio disparou outra, e as duas leram
   "este cliente ainda nao tem topico" antes de qualquer uma gravar. Cada uma
   abriu o seu.

   E' exatamente o defeito que eu ja tinha corrigido na montagem dos canais de
   idioma -- e nao apliquei aqui. Corrigir num lugar e esquecer do outro e' o
   jeito mais comum de um bug voltar. */
let montandoPainel = false;

async function montarPainelDoDono() {
  if (montandoPainel) return;
  montandoPainel = true;
  try {
    await montarPainelDoDonoAgora();
  } finally {
    montandoPainel = false;
  }
}

async function montarPainelDoDonoAgora() {
  const gid = await guildDoPainel();
  if (!gid) return;
  const guild = client.guilds.cache.get(gid);
  if (!guild) return;

  for (const nome of [CANAL_NOVOS, CANAL_PAGAMENTOS, CANAL_ERROS, CANAL_DIARIO, CANAL_ANALITICO]) {
    await canalDoPainel(guild, nome, null);
  }
  const sala = await canalDoPainel(guild, CANAL_CLIENTES, null);
  if (!sala) return;

  await garantirWebhookDePagamentos(guild);

  const todos = await sb("cyron_servidor?select=*&order=criado_em.asc") || [];
  for (const servidor of todos) {
    if (String(servidor.guild_id) === gid) continue;   // o painel nao e' cliente
    try {
      await acompanharNome(servidor);
      const topico = await topicoDoCliente(guild, sala, servidor);
      if (topico) await cartaoDoCliente(guild, servidor);
    } catch (e) {
      console.error("painel: cliente", servidor.nome, e?.message || e);
    }
  }

  await limparTopicosOrfaos(sala, todos);
}

/* Topico meu que nao pertence a cliente nenhum: sobra de duplicacao.

   So' apago o que EU abri (ownerId meu) e que nao esta apontado por nenhuma
   linha. Topico que o dono criou na mao fica onde esta -- apagar o que nao e'
   meu, num servidor que e' dele, seria passar por cima de uma decisao que nao
   me pertence. */
async function limparTopicosOrfaos(sala, servidores) {
  try {
    const meus = new Set(servidores.map((s) => s.canal_admin).filter(Boolean));
    const ativos = await sala.threads.fetchActive().catch(() => null);
    const velhos = await sala.threads.fetchArchived({ limit: 100 }).catch(() => null);

    for (const lista of [ativos?.threads, velhos?.threads]) {
      for (const [, t] of lista || []) {
        if (meus.has(t.id)) continue;
        if (t.ownerId !== client.user.id) continue;
        await t.delete("tópico duplicado do painel").catch(() => {});
        console.log(`painel: apaguei o tópico duplicado ${t.name}`);
      }
    }
  } catch (e) {
    console.error("painel: nao consegui limpar duplicados:", e?.message || e);
  }
}

/* O /admin: a metade do painel que responde perguntas.

   Canal por cliente mostra o historico de UM cliente. Aqui ficam as respostas
   que exigem olhar todos de uma vez -- quem usa mais, quantos existem, o que
   quebrou. E' de proposito que sejam duas coisas: tentar fazer a lista de
   canais responder isso e' o que ia frustrar em duas semanas. */
/* O painel do dono tambem no privado do bot: escrever "admin" (ou "painel")
   na DM abre o mesmo painel do /admin.

   O /admin de barra mora num servidor so', e o dono atende de outra conta,
   de outro lugar -- ir ate' o servidor certo so' para apertar um botao
   custava tempo toda vez. A DM e' o unico lugar onde o bot esta' sempre.

   A palavra e' conferida ANTES do ehDono: qualquer pessoa pode mandar
   "admin" no privado, e perguntar ao Discord quem e' dono a cada "oi" seria
   trabalho a toa. Quem nao e' dono cai na conversa de sempre, sem saber que
   existia outra porta. */
const PALAVRA_DO_PAINEL = /^\s*\/?(admin|painel)\s*$/i;

async function painelNoPrivado(msg) {
  if (!PALAVRA_DO_PAINEL.test(msg.content || "")) return false;
  if (!await ehDono(msg.author.id)) return false;
  await msg.channel.send({ embeds: [await embedDoResumo()], components: linhasDoAdmin() });
  return true;
}

async function comandoAdmin(inter) {
  /* O defer vem antes da checagem porque a checagem vai à rede: `ehDono`
     pergunta ao Discord de quem é o aplicativo, e com o cache frio isso é uma
     chamada dentro dos três segundos. Quem não é dono continua vendo a mesma
     recusa -- só depois de um "pensando" de um piscar de olhos. */
  await inter.deferReply({ flags: 64 });

  if (!await ehDono(inter.user.id)) {
    /* Nao digo "voce nao e' o dono" -- digo que o comando nao existe pra
       quem pergunta. Confirmar que existe um painel de dono e' contar metade
       do caminho pra quem estava tateando. */
    return inter.editReply({ content: "Não conheço esse comando." });
  }

  const gid = await guildDoPainel();
  if (!gid) {
    return inter.editReply({
      content: "Este servidor ainda não é o seu painel. Quer usar **este aqui** para acompanhar os clientes?",
      components: [{ type: 1, components: [
        { type: 2, custom_id: "admin:aqui", style: 3, emoji: { name: "📋" }, label: "Usar este servidor como painel" },
      ] }],
    });
  }

  return inter.editReply({ embeds: [await embedDoResumo()], components: linhasDoAdmin() });
}

/* As abas do /admin.

   Eram quinze botoes em tres fileiras, todos com o mesmo peso: o que se olha
   todo dia ao lado do que se usa uma vez por mes. Agora a primeira fileira e'
   um menu de abas, e cada aba traz so' os botoes dela. Os ids dos botoes sao
   os mesmos de antes: os formularios e quem os atende nao mudaram. */
const ABAS_DO_ADMIN = [
  { valor: "resumo", emoji: "📊", nome: "Visão geral", sobre: "o essencial e o que pede atenção" },
  { valor: "dinheiro", emoji: "💰", nome: "Dinheiro", sobre: "quem paga, quanto entra, quem vence" },
  { valor: "crescimento", emoji: "📈", nome: "Crescimento", sobre: "servidores e traduções em 14 dias" },
  { valor: "saude", emoji: "🩺", nome: "Saúde e erros", sobre: "relógio, tradutor, cotas e erros" },
  { valor: "servidores", emoji: "🔎", nome: "Servidores", sobre: "escolher um servidor e agir nele" },
  { valor: "ferramentas", emoji: "🧰", nome: "Ferramentas", sobre: "chaves, ajustes, códigos, suporte" },
];

/* O botao que mostra uma tela de dentro de uma aba continua naquela aba. */
const ABA_DO_BOTAO = { uso: "crescimento", erros: "saude", remontar: "ferramentas" };

function abaDoAdmin(acao) {
  if (ABA_DO_BOTAO[acao]) return ABA_DO_BOTAO[acao];
  return ABAS_DO_ADMIN.some((a) => a.valor === acao) ? acao : "resumo";
}

function linhasDoAdmin(aba = "resumo", servidores = []) {
  const menu = { type: 1, components: [{
    type: 3, custom_id: "admin:aba", placeholder: "Escolha uma aba",
    options: ABAS_DO_ADMIN.map((a) => ({ value: a.valor, label: a.nome, description: a.sobre,
      emoji: { name: a.emoji }, default: a.valor === aba })),
  }] };
  const botao = (id, emoji, label, style = 2) =>
    ({ type: 2, custom_id: `admin:${id}`, style, emoji: { name: emoji }, label });
  const convite = { type: 2, style: 5, emoji: { name: "➕" }, label: "Link para instalar", url: linkDeConvite() };
  const fileiras = {
    resumo: [[botao("resumo", "🔄", "Atualizar"), convite]],
    dinheiro: [[botao("dinheiro", "🔄", "Atualizar"), botao("codigos", "🎟️", "Gerar códigos", 1)]],
    crescimento: [[botao("crescimento", "🔄", "Atualizar"), botao("uso", "🏆", "Quem usa mais"),
      botao("diario", "📊", "Ver o diário agora")]],
    saude: [[botao("saude", "🔄", "Atualizar"), botao("erros", "🐛", "Erros um a um")]],
    servidores: [[botao("servidores", "🔄", "Atualizar"), botao("busca", "🔎", "Procurar por nome ou id", 1)]],
    ferramentas: [
      [botao("chaves", "🔑", "Chaves de tradução", 1), botao("visao", "👁️", "Leitura de imagem", 1),
        botao("fala", "🎧", "Áudio", 1), botao("ajustes", "⚙️", "Ajustes", 1), botao("codigos", "🎟️", "Gerar códigos")],
      [botao("comandos", "🧪", "Meus comandos"), botao("novocomando", "➕", "Novo comando", 4),
        botao("suporte", "🏗️", "Montar suporte"), botao("remontar", "🔄", "Remontar painel"), convite],
      [botao("ia", "🧠", "IA do privado", 1)],
    ],
  }[aba] || [];
  /* A lista de servidores e' um menu, e nao texto: escolher abre a ficha com
     os botoes de agir. Vinte e cinco e' o teto do Discord por menu; os
     primeiros sao os que mais usam, que sao os que mais pedem atencao. */
  const escolha = aba === "servidores" && servidores.length ? [{ type: 1, components: [{
    type: 3, custom_id: "admin:ficha", placeholder: "Abrir a ficha de um servidor",
    options: servidores.slice(0, 25).map((s) => ({
      value: String(s.id), label: String(s.nome || "sem nome").slice(0, 100),
      ...(s.linha ? { description: String(s.linha).slice(0, 100) } : {}),
    })),
  }] }] : [];
  return [menu, ...escolha, ...fileiras.map((c) => ({ type: 1, components: c }))];
}

/* A tela inteira de uma aba: o cartao e os botoes dela. */
async function telaDoAdmin(acao) {
  const aba = abaDoAdmin(acao);
  if (aba === "servidores") {
    const { embed, servidores } = await embedDosServidores();
    return { embeds: [embed], components: linhasDoAdmin(aba, servidores) };
  }
  const montar = { dinheiro: embedDoDinheiro, crescimento: embedDoCrescimento, saude: embedDeSaude,
    uso: embedDeUso, erros: embedDeErros, ferramentas: embedDasFerramentas }[acao]
    || { crescimento: embedDoCrescimento, saude: embedDeSaude, ferramentas: embedDasFerramentas }[aba]
    || embedDoResumo;
  return { embeds: [await montar()], components: linhasDoAdmin(aba) };
}

/* Quanto cada faixa custa por mes, em reais. O mesmo que PRECOS diz por
   extenso, em numero, para somar. */
const PRECO_MENSAL = { pro: 29.9, alianca: 79 };

function reais(v) {
  return "R$ " + (Number(v) || 0).toFixed(2).replace(".", ",");
}

/* Em que pe' esta' o pagamento de um servidor.

   Separa o que planoDe junta: para o bot, liberado na mao, teste e pago sao
   todos pago. Para quem olha o dinheiro, so' um deles paga. */
function situacaoDoPagamento(s) {
  if (s?.saiu_em) return "saiu";
  if (venceEm(s?.pago_ate)) return "pago";
  if (s?.plano === "pago") return "liberado";
  if (venceEm(s?.teste_ate)) return "teste";
  return "gratis";
}

function faixaPaga(s) {
  return s?.nivel === "pro" ? "pro" : "alianca";
}

async function embedDoResumo() {
  const todos = await sb("cyron_servidor?select=id,nome,plano,nivel,pago_ate,teste_ate,saiu_em") || [];
  const dentro = todos.filter((s) => !s.saiu_em);
  const pagando = dentro.filter((s) => situacaoDoPagamento(s) === "pago");
  const liberados = dentro.filter((s) => situacaoDoPagamento(s) === "liberado").length;
  const receita = pagando.reduce((a, s) => a + PRECO_MENSAL[faixaPaga(s)], 0);

  const uso = await sb(`cyron_uso_diario?dia=gte.${ontemISO()}&select=dia,caracteres,traducoes,do_cache`) || [];
  const somar = (dia) => uso.filter((l) => l.dia === dia).reduce((a, l) => ({
    c: a.c + Number(l.caracteres || 0), t: a.t + Number(l.traducoes || 0), k: a.k + Number(l.do_cache || 0),
  }), { c: 0, t: 0, k: 0 });
  const hoje = somar(hojeISO());
  const ontem = somar(ontemISO());
  const codigos = await sb("cyron_codigo?usado_em=is.null&select=codigo") || [];

  /* O que pede atencao vem com o caminho: cada linha diz em que aba olhar. */
  const semana = Date.now() + 7 * 864e5;
  const vencendo = pagando.filter((s) => venceEm(s.pago_ate) <= semana).length;
  const sairam = todos.filter((s) => s.saiu_em && Date.parse(s.saiu_em) >= Date.now() - 7 * 864e5).length;
  const atencao = [
    vencendo && `⏰ **${vencendo}** pagamento(s) vencem em 7 dias — aba 💰`,
    errosRecentes.length && `🐛 **${errosRecentes.length}** erro(s) guardados — aba 🩺`,
    tradutorFalhas.quedas && `🌐 o tradutor caiu no grátis **${tradutorFalhas.quedas}**x — aba 🩺`,
    cargoAcimaDeMim.size && `🔒 **${cargoAcimaDeMim.size}** servidor(es) com cargo acima do meu`,
    sairam && `👋 **${sairam}** servidor(es) saíram nesta semana — aba 📈`,
  ].filter(Boolean);

  return {
    color: 0x2E8B7A,
    title: "📊 CYRON — visão geral",
    fields: [
      { name: "Servidores", value: `**${dentro.length}** ativos\n${todos.length - dentro.length} saíram`, inline: true },
      { name: "Pagando", value: `**${pagando.length}** · ${reais(receita)}/mês` +
          (liberados ? `\n+${liberados} liberados na mão` : "") +
          (BETA || venceEm(BETA_ATE) ? "\n_beta: todos com limites do pago_" : ""), inline: true },
      { name: "Códigos livres", value: String(codigos.length), inline: true },
      { name: "Traduzido hoje", value: hoje.t
          ? `**${hoje.t}** traduções · ${emK(hoje.c)} caracteres · ${variacaoEmTexto(hoje.t, ontem.t)} vs ontem\n` +
            `${hoje.k} vieram do cache`
          : `_nada ainda_ · ontem foram ${ontem.t}` },
      { name: "🔔 Pede atenção", value: atencao.length ? atencao.join("\n") : "✅ nada — tudo em ordem" },
    ],
    footer: { text: "troque de aba no menu de cima" },
  };
}

/* Um grafico de barrinhas que cabe numa linha de texto.

   Embed nao desenha grafico, e uma imagem gerada custaria um servico a mais.
   Oito alturas bastam para ver a tendencia, que e' a pergunta. */
const BARRINHAS = "▁▂▃▄▅▆▇█";

function grafiquinho(valores) {
  const max = Math.max(0, ...valores);
  return valores.map((v) => BARRINHAS[max ? Math.round((Math.max(0, v) / max) * 7) : 0]).join("");
}

function variacaoEmTexto(agora, antes) {
  if (!antes) return agora ? "novo" : "igual";
  const p = Math.round(((agora - antes) / antes) * 100);
  if (!p) return "igual";
  return `${p > 0 ? "▲" : "▼"} ${Math.abs(p)}%`;
}

async function embedDoDinheiro() {
  const agora = Date.now();
  const todos = await sb("cyron_servidor?select=id,nome,plano,nivel,pago_ate,teste_ate,saiu_em") || [];
  const por = { pago: [], liberado: [], teste: [], gratis: [], saiu: [] };
  for (const s of todos) por[situacaoDoPagamento(s)].push(s);
  const receita = por.pago.reduce((a, s) => a + PRECO_MENSAL[faixaPaga(s)], 0);
  const quantos = (f) => por.pago.filter((s) => faixaPaga(s) === f).length;

  const semana = agora + 7 * 864e5;
  const vencendo = [...por.pago, ...por.teste]
    .map((s) => ({ s, ate: venceEm(s.pago_ate) || venceEm(s.teste_ate) }))
    .filter((x) => x.ate && x.ate <= semana)
    .sort((a, b) => a.ate - b.ate);
  /* Quem pagou e deixou vencer no ultimo mes: e' a lista de quem chamar. */
  const mes = agora - 30 * 864e5;
  const perdidos = todos.filter((s) => s.pago_ate && !venceEm(s.pago_ate) && s.plano !== "pago"
    && Date.parse(s.pago_ate) >= mes);
  const codigos = await sb("cyron_codigo?select=usado_em") || [];
  const livres = codigos.filter((c) => !c.usado_em).length;
  const usados = codigos.filter((c) => c.usado_em && Date.parse(c.usado_em) >= mes).length;

  const nome = (s) => String(s.nome || "sem nome").slice(0, 40);
  const lista = (xs, f) => xs.length
    ? xs.slice(0, 10).map(f).join("\n") + (xs.length > 10 ? `\n_e mais ${xs.length - 10}_` : "")
    : "_ninguém_";
  const beta = BETA || venceEm(BETA_ATE);

  return {
    color: 0xC9A227,
    title: "💰 Dinheiro",
    ...(beta ? { description: "_Beta ligado: todos usam os limites do pago, mas aqui só conta quem pagou de verdade._" } : {}),
    fields: [
      { name: "Entra por mês, se todos renovarem", value: `**${reais(receita)}**\n` +
          `Pro ${quantos("pro")} × ${reais(PRECO_MENSAL.pro)} · Aliança ${quantos("alianca")} × ${reais(PRECO_MENSAL.alianca)}` },
      { name: "Pagando", value: String(por.pago.length), inline: true },
      { name: "Em teste", value: String(por.teste.length), inline: true },
      { name: "Liberados na mão", value: String(por.liberado.length), inline: true },
      { name: "⏰ Vencem em 7 dias", value: lista(vencendo, ({ s, ate }) =>
          `• ${nome(s)} — ${quandoFoi(ate, "R")}${venceEm(s.pago_ate, agora) ? "" : " _(teste)_"}`) },
      { name: "💸 Não renovaram (30 dias)", value: lista(perdidos, (s) =>
          `• ${nome(s)} — venceu ${quandoFoi(Date.parse(s.pago_ate), "R")}`) },
      { name: "🎟️ Códigos", value: `${livres} livres · ${usados} usados em 30 dias`, inline: true },
      { name: "Grátis", value: String(por.gratis.length), inline: true },
    ],
    footer: { text: "estimativa pelo plano de cada servidor; não lê o extrato do banco" },
  };
}

async function embedDoCrescimento() {
  const DIAS = 14;
  const dias = Array.from({ length: DIAS }, (_, i) => diaISO(Date.now() - (DIAS - 1 - i) * 864e5));
  const uso = await sb(`cyron_uso_diario?dia=gte.${dias[0]}&select=dia,traducoes`) || [];
  const todos = await sb("cyron_servidor?select=nome,criado_em,saiu_em") || [];
  const escolhas = await sb("discord_idioma_jogador?select=idioma") || [];

  const porDia = new Map(dias.map((d) => [d, 0]));
  for (const l of uso) if (porDia.has(l.dia)) porDia.set(l.dia, porDia.get(l.dia) + Number(l.traducoes || 0));
  const serie = [...porDia.values()];
  const estaSemana = serie.slice(7).reduce((a, b) => a + b, 0);
  const antes = serie.slice(0, 7).reduce((a, b) => a + b, 0);

  const desde = Date.parse(dias[7]);
  const entraram = todos.filter((s) => Date.parse(s.criado_em) >= desde);
  const sairam = todos.filter((s) => s.saiu_em && Date.parse(s.saiu_em) >= desde);
  const entradas = dias.map((d) => todos.filter((s) => String(s.criado_em || "").slice(0, 10) === d).length);

  const conta = new Map();
  for (const e of escolhas) if (e.idioma) conta.set(e.idioma, (conta.get(e.idioma) || 0) + 1);
  const idiomas = [...conta].sort((a, b) => b[1] - a[1]).slice(0, 8);

  return {
    color: 0x3B82F6,
    title: "📈 Crescimento",
    fields: [
      { name: "Traduções em 14 dias", value: "```\n" + grafiquinho(serie) + "\n```" +
          `Esta semana **${emK(estaSemana)}** · a anterior ${emK(antes)} · ${variacaoEmTexto(estaSemana, antes)}` },
      { name: "Servidores", value: `**${todos.filter((s) => !s.saiu_em).length}** ativos\n` +
          `+${entraram.length} entraram · −${sairam.length} saíram em 7 dias`, inline: true },
      { name: "Entradas por dia", value: "```\n" + grafiquinho(entradas) + "\n```", inline: true },
      { name: "🆕 Chegaram nesta semana", value: entraram.length
          ? entraram.slice(-8).map((s) => `• ${String(s.nome || "sem nome").slice(0, 40)}`).join("\n")
          : "_ninguém_" },
      { name: "🌐 Idiomas dos membros", value: idiomas.length
          ? idiomas.map(([c, n]) => `${nomeDoIdioma(c)} **${n}**`).join(" · ")
          : "_ninguém escolheu ainda_" },
    ],
    ...(ultimosGraficos.dias ? { image: { url: ultimosGraficos.dias } } : {}),
    footer: { text: "cada barrinha é um dia, do mais antigo até hoje · gráfico completo em 📈-analitico" },
  };
}

async function embedDosServidores() {
  const todos = await sb("cyron_servidor?select=id,guild_id,nome,plano,nivel,pago_ate,teste_ate,saiu_em&order=criado_em.asc") || [];
  const uso = await sb(`cyron_uso_diario?dia=gte.${diaISO(Date.now() - 6 * 864e5)}&select=servidor_id,traducoes`) || [];
  const soma = new Map();
  for (const l of uso) soma.set(l.servidor_id, (soma.get(l.servidor_id) || 0) + Number(l.traducoes || 0));
  const ativos = todos.filter((s) => !s.saiu_em)
    .sort((a, b) => (soma.get(b.id) || 0) - (soma.get(a.id) || 0));

  const selo = { pago: "🟢", liberado: "🔵", teste: "🟡", gratis: "⚪", saiu: "⚫" };
  const dia = (t) => new Date(t).toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" });
  const plano = (s) => {
    const sit = situacaoDoPagamento(s);
    const faixa = nomeDaFaixa(faixaPaga(s));
    if (sit === "pago") return `${faixa} até ${dia(venceEm(s.pago_ate))}`;
    if (sit === "teste") return `teste até ${dia(venceEm(s.teste_ate))}`;
    if (sit === "liberado") return `${faixa} liberado`;
    return "grátis";
  };
  const linhas = ativos.slice(0, 25).map((s) =>
    `${selo[situacaoDoPagamento(s)]} **${String(s.nome || "sem nome").slice(0, 40)}** · ${plano(s)} · ${soma.get(s.id) || 0} trad.`);

  return {
    embed: {
      color: 0x2E8B7A,
      title: `🔎 Servidores — ${ativos.length} ativos`,
      description: (linhas.length ? linhas.join("\n") : "_nenhum servidor ainda_") +
        (ativos.length > 25 ? `\n_e mais ${ativos.length - 25}: use 🔎 Procurar_` : "") +
        "\n\n🟢 pagando · 🟡 teste · 🔵 liberado na mão · ⚪ grátis",
      footer: { text: "traduções dos últimos 7 dias · escolha um no menu para agir" },
    },
    servidores: ativos.map((s) => ({ id: s.id, nome: s.nome, linha: `${plano(s)} · ${soma.get(s.id) || 0} traduções em 7 dias` })),
  };
}

